def coin_change(coins, amount):
    if amount == 0:
        return 0
    from collections import deque
    q = deque([(0, 0)])
    seen = {0}
    while q:
        cur, steps = q.popleft()
        for c in coins:
            nxt = cur + c
            if nxt == amount:
                return steps + 1
            if nxt < amount and nxt not in seen:
                seen.add(nxt)
                q.append((nxt, steps + 1))
    return -1

